alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members bm
    where bm.board_id = p_board_id
      and bm.user_id = auth.uid()
  );
$$;

create or replace function public.is_board_editor(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members bm
    where bm.board_id = p_board_id
      and bm.user_id = auth.uid()
      and bm.role = 'editor'
  );
$$;

create or replace function public.is_board_active(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived = false
  );
$$;

create or replace function public.enforce_card_board_editorship()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    if not public.is_board_editor(new.board_id) then
      raise exception 'only editors can move cards';
    end if;
  else
    if not public.is_board_editor(old.board_id) then
      raise exception 'only editors can edit cards';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_card_board_editorship
before update on public.cards
for each row execute function public.enforce_card_board_editorship();

