on public.boards
for select
to authenticated
using (public.is_board_member(id));

create policy board_members_select_member
on public.board_members
for select
to authenticated
using (public.is_board_member(board_id));

create policy cards_select_member
on public.cards
for select
to authenticated
using (public.is_board_member(board_id));

create policy cards_insert_editor
on public.cards
for insert
to authenticated
with check (public.is_board_editor(board_id));

create policy cards_update_editor
