```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend_of(p_user_id uuid, p_other_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = p_user_id and f.addressee_id = p_other_id)
       or (f.requester_id = p_other_id and f.addressee_id = p_user_id)
       and f.status = 'accepted'
  );
$$;

create or replace function public.posts_enforce_author()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.author_id is distinct from auth.uid() then
      raise exception 'posts.author_id must match the current user';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.author_id is distinct from old.author_id then
      raise exception 'posts.author_id cannot be changed';
    end if;
  end if;
  return new;
end;
$$;

create trigger posts_enforce_author
before insert or update on public.posts
for each row execute function public.posts_enforce_author();

create policy posts_select on public.posts
for select to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or public.is_friend_of(auth.uid(), author_id)
);

create policy posts_insert on public.posts
for insert to authenticated
with check (author_id = auth.uid());

create policy posts_update on public.posts
for update to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy posts_delete on public.posts
for delete to authenticated
using (author_id = auth.uid());

create policy friendships_select on public.friendships
for select to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy friendships_insert on public.friendships
for insert to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy friendships_update on public.friendships
for update to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy friendships_delete on public.friendships
for delete to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

revoke all on public.posts from anon;
revoke all on public.friendships from anon;

grant select on public.posts to anon;
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;

grant all on public.posts to service_role;
grant all on public.friendships to service_role;

revoke all on sequence public.posts_id_seq from anon;
grant usage, select on sequence public.posts_id_seq to authenticated, service_role;
