returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_admins
    where user_id = auth.uid()
  );
$$;

revoke all on function public.is_org_admin() from public;
grant execute on function public.is_org_admin() to authenticated, service_role;

create policy "files_select_own_or_admin"
on public.files
for select
to authenticated
using (
  owner_id = auth.uid()
  or public.is_org_admin()
);

create policy "files_insert_own"
on public.files
for insert
to authenticated
with check (
  owner_id = auth.uid()
  and not legal_hold
);

create policy "files_update_own_or_admin"
on public.files
for update
