alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

create or replace function public.is_resident_of(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.is_staff_of_building(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.can_see_request(p_request_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.requests r
    join public.units u on u.id = r.unit_id
    where r.id = p_request_id
      and (
        public.is_resident_of(u.id)
        or public.is_staff_of_building(u.building_id)
      )
  );
$$;

create or replace function public.enforce_request_update_columns()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only the status of a request can be updated';
  end if;

  if new.status not in ('open', 'in_progress', 'done') then
    raise exception 'Invalid request status';
  end if;

  if not public.is_staff_of_building(old.unit_id::bigint) then
    raise exception 'Only building staff can update a request';
  end if;

  return new;
end;
$$;

create trigger enforce_request_update_columns
before update on public.requests
for each row execute function public.enforce_request_update_columns();

create policy "units_select_visible_to_owner_or_staff"
on public.units
for select
to authenticated
using (
  public.is_resident_of(id)
  or public.is_staff_of_building(building_id)
);

create policy "residents_select_own"
on public.residents
for select
