alter table public.support_agents enable row level security;
alter table public.supervisors enable row level security;
alter table public.customers enable row level security;

create or replace function public.is_support_agent()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.support_agents sa
    where sa.user_id = auth.uid()
  );
$$;

create or replace function public.is_supervisor()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.supervisors s
    where s.user_id = auth.uid()
  );
$$;

create or replace function public.support_agent_region()
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.region
  from public.support_agents s
  where s.user_id = auth.uid();
$$;

create or replace function public.mask_email(p_email text)
returns text
language sql
immutable
as $$
  select case
    when p_email is null then null
    when p_email = '' then ''
    else
      left(p_email, 1) || '***' ||
      case
        when position('@' in p_email) > 0
        then substring(p_email from position('@' in p_email))
        else p_email
      end
  end;
$$;

create or replace function public.mask_phone(p_phone text)
returns text
language sql
immutable
as $$
  select case
    when p_phone is null then null
    when p_phone = '' then ''
    else '******' || right(p_phone, 4)
  end;
$$;

create or replace function public.enforce_read_only()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role'
     or current_user in ('service_role', 'postgres', 'supabase_admin')
     or pg_catalog.pg_has_role(current_user, 'service_role', 'member')
  then
    return new;
  end if;

  if tg_op = 'INSERT' or tg_op = 'UPDATE' or tg_op = 'DELETE' then
    raise exception 'customers, support_agents, and supervisors are read-only for app users';
  end if;

  return new;
end;
$$;

create trigger customers_enforce_read_only
before insert or update or delete on public.customers
for each row execute function public.enforce_read_only();

