with (security_invoker = false)
as
select
  c.id,
  c.region,
  c.full_name,
  public.mask_email(c.email) as email_masked,
  public.mask_phone(c.phone) as phone_masked
from public.customers c
where public.is_supervisor()
   or (public.is_support_agent() and c.region = public.support_agent_region());

