```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy "Authenticated users can view all auctions"
on public.auctions
for select
to authenticated
using (true);

create policy "Users can view their own bids or bids on their auctions"
on public.bids
for select
to authenticated
using (
  bidder_id = auth.uid()
  or exists (
    select 1
    from public.auctions a
    where a.id = bids.auction_id
      and a.seller_id = auth.uid()
  )
);

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_new_bid_id bigint;
  v_new_highest numeric;
begin
  if v_caller is null then
    raise exception 'Not authenticated';
  end if;

  select *
  into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at < now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_caller then
    raise exception 'Cannot bid on your own auction';
  end if;

  if p_amount <= 0 then
    raise exception 'Bid amount must be positive';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    if p_amount <= v_auction.highest_bid + v_auction.min_increment then
      raise exception 'Bid must be higher than current highest bid plus minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_caller, p_amount)
  returning id into v_new_bid_id;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_caller
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on public.auctions from anon;
revoke all on public.bids from anon;
revoke all on public.auctions from authenticated;
revoke all on public.bids from authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;

grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant usage, select on sequence public.bids_id_seq to service_role;

revoke all on function public.place_bid(bigint, numeric) from public;
revoke all on function public.place_bid(bigint, numeric) from anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
grant execute on function public.place_bid(bigint, numeric) to service_role;
```

