create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_bidder_count integer;
  v_current_highest numeric;
  v_is_ending boolean;
begin
  if v_caller is null then
    raise exception 'Not authenticated';
  end if;

  select *
  into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_caller then
    raise exception 'Cannot bid on own auction';
  end if;

  select count(*)
  into v_bidder_count
  from public.bids
  where auction_id = p_auction_id;

  if v_auction.highest_bid is null then
    v_current_highest := v_auction.starting_price;
  else
    v_current_highest := v_auction.highest_bid;
  end if;

  if p_amount <= v_current_highest + v_auction.min_increment then
    raise exception 'Bid must be higher than current highest bid plus minimum increment';
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_caller, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_caller
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from PUBLIC;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
