```sql
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create or replace function public.is_class_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and c.instructor_id = auth.uid()
  );
$$;

create or replace function public.can_enroll_in_class(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and c.instructor_id <> auth.uid()
      and (
        select count(*)
        from public.class_spots s
        where s.class_id = c.id
          and s.status = 'enrolled'
      ) < c.capacity
  );
$$;

create or replace function public.class_spot_immutable_columns()
returns trigger
language sql
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'class_spot user_id must match the authenticated user';
    end if;
    return new;
  end if;

  if new.class_id is distinct from old.class_id
     or new.user_id is distinct from old.user_id then
    raise exception 'class_spot class_id and user_id cannot be changed';
  end if;

  if new.status is distinct from old.status then
    if old.status <> 'waitlisted' then
      raise exception 'only waitlisted spots can be moved to enrolled';
    end if;
    if new.status <> 'enrolled' then
      raise exception 'status can only move from waitlisted to enrolled';
    end if;
    if not public.can_enroll_in_class(old.class_id) then
      raise exception 'no room in the class';
    end if;
  end if;

  return new;
end;
$$;

create trigger class_spot_immutable_columns
before update on public.class_spots
for each row execute function public.class_spot_immutable_columns();

create policy classes_select_authenticated
on public.classes
for select
to authenticated
using (true);

create policy class_spots_select_own_or_instructor
on public.class_spots
for select
to authenticated
using (
  user_id = auth.uid()
  or public.is_class_instructor(class_id)
);

create policy class_spots_insert_own
on public.class_spots
for insert
to authenticated
with check (
  user_id = auth.uid()
  and status in ('enrolled', 'waitlisted')
  and (
    status = 'enrolled'
    and public.can_enroll_in_class(class_id)
  )
);

create policy class_spots_update_own_waitlisted
on public.class_spots
for update
to authenticated
using (
  user_id = auth.uid()
  and status = 'waitlisted'
)
with check (
  user_id = auth.uid()
  and status = 'enrolled'
);

create policy class_spots_delete_own_or_instructor
on public.class_spots
for delete
to authenticated
using (
  user_id = auth.uid()
  or public.is_class_instructor(class_id)
);

revoke all on public.classes from anon;
revoke all on public.class_spots from anon;

revoke all on public.classes from authenticated;
revoke all on public.class_spots from authenticated;

